const cases=[
  {id:'delivery',name:'Delivery tracking',prompt:'Design live order tracking for a local delivery service. What should the customer see as the courier approaches?',user:'A customer waiting for an active order',moment:'knowing when to meet the courier',metric:'ETA error near arrival and “where is my order?” contacts',decision:'Use adaptive location updates: less frequent while far away, faster during the final approach.',failure:'When location is stale, show the last-update time and a cautious ETA rather than a moving dot.',nodes:[['Customer app','client',3,70,270],['Tracking API','service',4,285,270],['Order state','database',5,510,160],['ETA service','service',5,510,360],['Courier app','client',3,65,70],['Location ingest','service',4,285,70]],edges:[[4,5,'GPS'],[5,2,'latest position'],[2,3,'order + location'],[3,1,'ETA'],[1,0,'updates']]},
  {id:'notifications',name:'Social notifications',prompt:'A large social app needs to alert people about useful activity without overwhelming them. Sketch the system.',user:'A person who wants to know about meaningful social activity',moment:'receiving timely, relevant alerts without overload',metric:'useful notification open rate and opt-out rate',decision:'Send urgent direct interactions promptly; batch lower-priority activity into digests.',failure:'If delivery is delayed, retain the event and avoid duplicate sends when workers retry.',nodes:[['Social event','event',3,55,80],['Event queue','queue',4,275,80],['Preference store','database',5,490,240],['Policy + ranking','service',5,485,80],['Delivery worker','service',6,700,80],['User device','client',3,700,300]],edges:[[0,1,'event'],[1,3,'work item'],[2,3,'settings'],[3,4,'send decision'],[4,5,'push']]},
  {id:'feed',name:'Real-time feed ranking',prompt:'Sketch a system that serves a fresh, personalised first page of content quickly.',user:'A person opening a feed to see relevant, fresh content',moment:'getting a useful feed quickly',metric:'meaningful engagement, latency, and hide/report rate',decision:'Use a fast candidate set and cached features, then rerank with fresh signals where they materially help.',failure:'If ranking is slow or unavailable, return a safe fallback feed with a clear latency budget.',nodes:[['Feed client','client',3,65,270],['Feed API','service',4,280,270],['Candidate store','database',5,485,70],['Feature store','cache',5,485,245],['Ranker','service',6,700,170],['Content events','event',3,65,70]],edges:[[5,2,'new posts'],[2,4,'candidates'],[3,4,'features'],[1,4,'request'],[4,1,'ranked items'],[1,0,'feed']]},
  {id:'scheduling',name:'Cross-surface scheduling',prompt:'Creators want to schedule one post across several publishing channels. Design the flow from request to result.',user:'A creator scheduling content for several publishing channels',moment:'knowing a post will publish at the chosen time on each surface',metric:'on-time publish success and failed-post recovery rate',decision:'Store one schedule request, then dispatch surface-specific jobs with idempotent retries.',failure:'If one surface fails, keep others independent and show a per-surface status with a retry path.',nodes:[['Creator UI','client',3,65,250],['Schedule API','service',4,280,250],['Schedule store','database',5,495,90],['Job queue','queue',5,495,290],['Publish workers','service',6,700,290],['Surface APIs','service',6,700,85],['Scheduler','service',5,295,90]],edges:[[0,1,'schedule'],[1,2,'save'],[2,6,'due record'],[6,3,'due jobs'],[3,4,'tasks'],[4,5,'publish'],[4,1,'result']]}
];
const lessons=[
  {title:'Clarify the brief',intro:'Start with the product question, then ask only the clarifying questions that would change the design. Ask about the user, scale, core problem, success, latency, reliability, and MVP scope.',task:c=>`For ${c.name.toLowerCase()}, write 3–5 questions you would ask. State the primary user and an MVP boundary. Add a user card and a note with your assumptions.`,checks:['Identify one primary user and job.','Ask about scale and latency or reliability.','State what is in the MVP and what is deferred.'],answer:c=>`I’ll focus on ${c.user.toLowerCase()}. The core job is ${c.moment}. I would ask about expected scale, acceptable delay, reliability needs, and whether this is MVP or full product. I’ll assume a narrow MVP that solves that moment first.`},
  {title:'Describe the experience',intro:'Work backward from what the user needs to see and do. Describe the journey first, then design the system around it.',task:c=>`Write a 4-step user journey for ${c.name.toLowerCase()}. Put the key user action and resulting experience on the board as notes.`,checks:['The first step is a real entry point.','Each step names a visible user outcome.','The journey has a clear end state.'],answer:c=>`The user enters the experience, sees the current state, receives an important update, and reaches the outcome: ${c.moment}. I would keep the journey narrow enough to explain in under a minute.`},
  {title:'Translate UX to requirements',intro:'Connect the user need to an experience requirement, a technical implication, and a trade-off. A product choice should create a visible system requirement.',task:c=>`Write one full need, experience, technical requirement, and trade-off chain for ${c.moment}. Use a note for each link in the chain and connect them.`,checks:['The technical need follows from the promised UX.','Name a measurable freshness, latency, scale, or reliability requirement.','State the cost of meeting it.'],answer:c=>`Need: ${c.moment}. UX: show trustworthy, timely state. Technical implication: deliver updates within a defined delay and keep the underlying data current. Trade-off: fresher data consumes more compute, network, or operational complexity.`},
  {title:'Draw the main data flow',intro:'Trace one user action or event from its source to the result on screen. Draw arrows with the data moving between components.',task:c=>`Build the main flow for ${c.name.toLowerCase()}. Add client, service, and data cards. Connect the source of the event to the user-visible result.`,checks:['Show the event or action that starts the flow.','Show which service processes it and where state lives.','Show how the response reaches the user.'],answer:c=>`A source event enters an API or ingestion service, is validated and stored, processed into a user-facing result, then returned or pushed to the client. Every arrow should name the data or action it carries.`},
  {title:'Give each component a job',intro:'Major components might include clients, servers, databases, caches, and queues. Name only those needed, and explain what each does.',task:c=>`Label at least four cards on your diagram. For each, explain its responsibility in the reasoning box. Add a queue or cache only if it solves a real problem.`,checks:['Each component has one clear responsibility.','Storage has a stated purpose.','Queue or cache is justified by scale, speed, or reliability.'],answer:c=>`I would identify the client, an API/ingestion service, the core processing service, and storage. I’d add a queue for burst smoothing or retries, or a cache for fast repeated reads, only if the product requirement calls for it.`},
  {title:'Commit to a trade-off',intro:'The best answer makes a call. Compare two plausible choices against the user need, then say what evidence would make you change direction.',task:c=>`Choose one major architectural trade-off for ${c.name.toLowerCase()}. Put your recommendation and the rejected alternative in separate notes.`,checks:['Compare real alternatives.','Explain the user impact and system cost.','Commit to a choice and reversal condition.'],answer:c=>c.decision+' I would revisit this choice if measured user harm, latency, cost, or reliability changed the balance.'},
  {title:'Design the failure path',intro:'An engineer will probe the uncomfortable case: data is stale, a service is down, or a retry duplicates an action. Tie the fallback to user trust.',task:c=>`Add a failure note to the board. Explain what the system does and what the user sees when the main flow breaks.`,checks:['Name the failure precisely.','Show a safe fallback or recovery path.','Keep the UI honest about uncertainty.'],answer:c=>c.failure},
  {title:'Evaluate and present',intro:'Close with success and guardrails. Give a short opening that connects the experience to the diagram, trade-off, and failure path; let the interviewer choose a drill-down.',task:c=>`Write a 60–90 second answer for the sample question. Refer to your diagram, name your trade-off, and finish with success and guardrail metrics.`,checks:['Lead with the user and core experience.','Walk the main data flow clearly.','Defend a trade-off and a failure path.','End with outcome and guardrail metrics.'],answer:c=>`I’ll design for ${c.user.toLowerCase()}, whose key need is ${c.moment}. My diagram starts at the source event, passes through an API and processing service, stores the current state, and serves the result to the client. ${c.decision} ${c.failure} I’d measure ${c.metric}. I can go deeper on the component boundaries or the trade-off.`}
];
const caseAnswers={
  delivery:[
    'I would ask: Are we designing for the customer or courier? When does tracking start? How fresh must the location feel near arrival? What is the expected active-order scale? Is the MVP status, ETA, and map only? I will focus on the customer after pickup.',
    'The customer opens the active order, sees status and ETA, watches the courier approach when close, and gets a delivered confirmation. A meaningful ETA change or arrival can trigger an alert.',
    'Need: know when to meet the courier. UX: current location and a reliable ETA near arrival. Technical implication: recent courier GPS, ETA recomputation, and a client update path. Trade-off: more frequent updates improve freshness but consume battery, network, and compute.',
    'Courier app sends GPS to location ingestion. Ingestion validates the order and stores the latest position. ETA service combines position with route and order state. Tracking API returns status, last-known position, and ETA to the customer app; significant changes can also be pushed.',
    'Courier client collects GPS; ingestion validates and associates updates with an active order; active-order store holds latest state; ETA service estimates arrival; tracking API serves the customer. A queue can smooth location bursts if traffic warrants it.',
    'I would use adaptive updates: slower while the courier is far away and faster near arrival. A fixed five-second cadence wastes battery and compute; a fixed five-minute cadence feels stale near handoff. I would tune the policy using observed ETA error, user behavior, and cost.',
    'If GPS is stale, retain the last known position with a timestamp, show tracking as temporarily unavailable, and widen or suppress the ETA if confidence falls. Resume from fresh updates when the courier reconnects; do not replay old points as live movement.',
    'I am designing customer tracking for an active order. The key need is knowing when to meet the courier. Courier GPS enters an ingestion service, updates active-order state, and feeds ETA estimation. The tracking API serves current state to the customer app. I would increase update frequency near arrival, balancing freshness against battery and cost. If GPS is stale, the UI says so. I would measure ETA error and “where is my order?” contacts, with stale-location rate and battery use as guardrails.'
  ],
  notifications:[
    'I would ask which events count, which are urgent, which channels are in scope, what user preferences must be respected, and what delivery latency is acceptable at large scale. I will focus on in-app and push alerts for social interactions, with user controls.',
    'A user receives a relevant alert, opens it to the related content, can mute or tune that category, and sees lower-priority activity bundled rather than arriving as a stream of interruptions.',
    'Need: hear about important social activity without overload. UX: prompt direct-interaction alerts, quieter digests for low-priority events, and working controls. Technical implication: event classification, preference lookup, scheduling, and channel delivery. Trade-off: urgency versus interruption and delivery cost.',
    'A social action emits an event to a queue. A policy service checks recipient, deduplicates, applies preferences and ranking, then sends an eligible alert to delivery workers. Workers send via the relevant channel and record outcome. The client opens the linked content.',
    'Event producers create notifications; a durable queue buffers bursts; policy service filters and ranks; preference store holds opt-outs and quiet hours; delivery workers send through channels; a status store tracks attempts. A queue is warranted by traffic bursts and retries.',
    'I would send high-value direct interactions promptly, but batch lower-value activity. Sending everything immediately improves timeliness but creates fatigue and opt-outs. I would change thresholds based on user engagement, opt-outs, and critical-event misses.',
    'If delivery workers fail, keep the event in a durable queue, retry with bounded backoff, and use an idempotency key so the user is not alerted twice. If preferences are unavailable, avoid sending an alert whose consent or quiet-hour status is uncertain.',
    'At large scale, the challenge is relevance and reliable delivery. Events enter a durable queue; policy checks recipient preferences, deduplicates, and ranks before workers send push or in-app alerts. I would send direct interactions promptly and batch weaker signals. Retries must be idempotent. I would measure useful opens and opt-outs, with duplicate and late sends as guardrails.'
  ],
  feed:[
    'I would ask what “real time” means, the latency target, which content is eligible, whether ranking is personalized, expected request volume, and what failure fallback is acceptable. I will focus on a personalized first-page feed for an active user.',
    'The user opens the feed, sees a fast first set of relevant posts, scrolls for more, and gets newer content when refreshing. Hides or reports should influence later ranking.',
    'Need: a relevant and fresh feed without waiting. UX: a first page within a clear latency budget, with recent posts mixed in. Technical implication: candidate retrieval, feature access, ranking, and pagination. Trade-off: richer ranking versus response time and compute.',
    'Feed client requests a page. Feed API retrieves eligible candidates and user/content features, passes them to a ranker, applies filtering and diversity rules, and returns items plus a pagination cursor. Content and interaction events update candidate and feature stores asynchronously.',
    'Feed API handles requests and cursors; candidate store supplies eligible posts; feature store supplies user and content signals; ranker scores candidates; post-processing enforces blocks, safety, and diversity. Caches can accelerate hot features, with freshness limits stated explicitly.',
    'I would retrieve a broad but bounded candidate set quickly, use cached features where acceptable, and spend extra model compute only on the candidates likely to be shown. A larger, fresher ranking pass may improve relevance but hurts latency and cost. I would tune it against quality and tail latency.',
    'If the ranker is slow or down, return a safe fallback set of eligible recent posts within the latency budget. Do not bypass blocking, privacy, or safety checks. Record degraded responses so the fallback does not silently become the normal experience.',
    'I will design the first personalized feed page. The client requests it from a feed API, which retrieves eligible candidates and features, ranks them, applies safety and diversity rules, and returns a page with a cursor. Content and interaction events refresh the stores. I would bound candidate count and model cost to protect latency, and use a safe fallback if ranking fails. I would measure meaningful engagement and latency, with hide/report rate as a guardrail.'
  ],
  scheduling:[
    'I would ask which surfaces are supported, whether each has distinct validation rules, the required on-time window, how edits/cancellations work, expected volume, and what partial failure should look like. I will focus on scheduling one post to selected surfaces.',
    'The creator composes a post, selects surfaces and a time, sees validation for each surface, confirms the schedule, and later sees per-surface published or failed status with a recovery option.',
    'Need: trust that each post publishes at the chosen time. UX: clear per-surface schedule and outcome. Technical implication: durable schedule record, due-time dispatcher, separate surface jobs, and status tracking. Trade-off: one simple operation versus independent per-surface reliability and complexity.',
    'Creator UI sends a schedule request to the API. The API validates and saves one schedule plus per-surface targets. A scheduler detects due records and enqueues one job per surface. Workers call each surface API and write success or failure status, which the UI reads.',
    'Schedule API validates and stores requests; schedule store is the durable source of truth; scheduler releases due jobs; queue decouples timed dispatch from publication; surface-specific workers call publishing APIs; status store records each outcome. Idempotency prevents duplicate posts on retry.',
    'I would create independent jobs per selected surface. This makes partial success visible and retries targeted, though it adds coordination and status complexity. I would avoid an all-or-nothing transaction across surfaces because one API failure should not block another publish.',
    'If one surface API fails, retry that surface with an idempotency key and backoff while retaining success states for the others. Show a per-surface failure and recovery option. Cancellation must stop jobs that have not published, but cannot undo a completed post without a separate delete flow.',
    'I will design scheduling for a creator posting to several surfaces. The API validates the request and stores a durable schedule. A scheduler releases one due job per surface; workers publish and record per-surface results. This choice isolates failures and allows targeted retries, at the cost of status coordination. I would use idempotency to prevent duplicate posts and show partial outcomes clearly. I would measure on-time success and recovery rate, with duplicate posts as a guardrail.'
  ]
};
lessons.forEach((lesson,index)=>{lesson.answer=c=>caseAnswers[c.id][index]});
const key='pa-lab-v1';let db;try{db=JSON.parse(localStorage.getItem(key))}catch{}if(!db||typeof db!=='object')db={caseId:'delivery',step:0,cases:{}};for(const c of cases)if(!db.cases[c.id])db.cases[c.id]={nodes:[],edges:[],notes:{}};
let selected=null,exampleMode=false,toastTimer,drag=null,linkDrag=null,lastTap=null;
const $=s=>document.querySelector(s),caseNow=()=>cases.find(c=>c.id===db.caseId)||cases[0],work=()=>db.cases[db.caseId];
function save(){localStorage.setItem(key,JSON.stringify(db))}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function status(s){$('#board-status').textContent=s}function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function renderCourse(){const c=caseNow(),l=lessons[db.step];$('#case-select').innerHTML=cases.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('#case-select').value=c.id;$('#case-prompt').textContent=c.prompt;$('#lesson-nav').innerHTML=lessons.map((x,i)=>`<button type="button" class="lesson-link ${i===db.step?'active':''}" data-step="${i}"><span class="lesson-num">${i+1}</span>${esc(x.title)}</button>`).join('');$('#step-kicker').textContent=`Step ${db.step+1} of ${lessons.length}`;$('#step-title').textContent=l.title;$('#step-intro').textContent=l.intro;$('#step-task').textContent=l.task(c);$('#step-checks').innerHTML=l.checks.map(x=>`<li>${esc(x)}</li>`).join('');$('#reasoning').value=work().notes[db.step]||'';$('#example-text').textContent=l.answer(c);$('#example-panel').hidden=true;$('#reveal-answer').textContent='Reveal worked answer';$('#next-step').textContent=db.step===lessons.length-1?'Start another case':'Next step';const completed=Object.values(work().notes).filter(x=>x.trim()).length;$('#progress-label').textContent=`${completed} of ${lessons.length} written reflections`;$('#progress-fill').style.width=`${completed/lessons.length*100}%`;renderBoard()}
function normalNodes(){return work().nodes}function boardData(){if(!exampleMode)return {nodes:normalNodes(),edges:work().edges};const c=caseNow(),limit=db.step<3?3:6,visible=c.nodes.filter(n=>n[2]<=limit),scale=Math.max(.55,Math.min(1,($('#board').clientWidth-190)/700));return {nodes:visible.map((n,i)=>({id:`ex${i}`,label:n[0],type:n[1],x:Math.round(n[3]*scale),y:n[4]})),edges:c.edges.filter(e=>visible.includes(c.nodes[e[0]])&&visible.includes(c.nodes[e[1]])).map(e=>({from:`ex${visible.indexOf(c.nodes[e[0]])}`,to:`ex${visible.indexOf(c.nodes[e[1]])}`,label:e[2]}))}}
function renderBoard(){const {nodes,edges}=boardData(),board=$('#board'),layer=$('#nodes');board.classList.toggle('showing-example',exampleMode);board.querySelector('.edge-editor')?.remove();layer.innerHTML=nodes.map(n=>`<div class="node ${n.type==='note'?'note':''} type-${n.type==='service'||n.type==='component'?'server':n.type} ${selected===n.id&&!exampleMode?'selected':''}" data-id="${esc(n.id)}" tabindex="0" role="button" aria-label="${esc(n.label)} ${esc(n.type)}" style="left:${n.x}px;top:${n.y}px"><span class="node-glyph" aria-hidden="true"></span><span class="node-title">${esc(n.label)}</span><span class="node-type">${esc(n.type==='service'?'server / service':n.type)}</span><span class="node-port" data-port="${esc(n.id)}" role="button" tabindex="0" aria-label="Drag to connect from ${esc(n.label)}"></span></div>`).join('');$('#empty-board').style.display=nodes.length?'none':'grid';const w=board.clientWidth,h=board.clientHeight,svg=$('#edges');svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.innerHTML=`<defs><marker id="arrowhead" markerWidth="9" markerHeight="7" refX="8" refY="3.5" orient="auto"><polygon points="0 0,9 3.5,0 7" fill="#20221f"/></marker></defs>`+edges.map((e,index)=>{const a=nodes.find(n=>n.id===e.from),b=nodes.find(n=>n.id===e.to);if(!a||!b)return '';let x1=a.x+80,y1=a.y+30,x2=b.x+80,y2=b.y+30;const dx=x2-x1,dy=y2-y1,d=Math.hypot(dx,dy)||1;x1+=dx/d*65;y1+=dy/d*27;x2-=dx/d*65;y2-=dy/d*27;return `<path class="edge" d="M${x1} ${y1} L${x2} ${y2}" marker-end="url(#arrowhead)"/><text class="edge-label" data-edge="${index}" tabindex="0" role="button" aria-label="Edit connection label ${esc(e.label||'data')}" x="${(x1+x2)/2}" y="${(y1+y2)/2-7}" text-anchor="middle">${esc(e.label||'data')}</text>`}).join('')+'<line id="drag-line" x1="0" y1="0" x2="0" y2="0" style="display:none" />';$('#show-example').textContent=exampleMode?'Back to my board':'Show example';$('#show-example').classList.toggle('active',exampleMode);$('#add-component').disabled=exampleMode;$('#component-type').disabled=exampleMode;$('#add-note').disabled=exampleMode;$('#add-text').disabled=exampleMode;$('#delete-selected').disabled=exampleMode;$('#rename-selected').disabled=exampleMode||!selected}
function addNode(type){if(exampleMode)return;const label=type==='note'?'New note':type==='text'?'Add text':`New ${type}`,count=normalNodes().length,cols=Math.max(1,Math.floor(($('#board').clientWidth-20)/205));const n={id:`n${Date.now()}${Math.random().toString(36).slice(2,5)}`,label,type,x:Math.max(20,Math.min(40+(count%cols)*205,$('#board').clientWidth-190)),y:Math.max(30,Math.min(70+Math.floor(count/cols)*115,$('#board').clientHeight-90))};if(type==='text'){n.x=40;n.y=Math.max(40,Math.min($('#board').clientHeight-100,420+normalNodes().filter(x=>x.type==='text').length*110))}normalNodes().push(n);selected=n.id;save();renderBoard();status(type==='text'?'Type your annotation, then drag it into place.':'Double-click the new card to rename it, then drag it into place.');if(type==='text')renameNode(n.id)}
function renameNode(id){
  const n=normalNodes().find(x=>x.id===id),el=[...$('#nodes').querySelectorAll('.node')].find(x=>x.dataset.id===id);
  if(!n||!el||el.querySelector('input,textarea'))return;
  selected=id;const title=el.querySelector('.node-title'),editor=document.createElement(n.type==='text'?'textarea':'input');
  editor.className='node-rename';if(n.type==='text'){editor.rows=3;editor.maxLength=500}else{editor.type='text';editor.maxLength=80}
  editor.value=n.label;editor.setAttribute('aria-label',n.type==='text'?'Edit board text':'Rename component');
  title.replaceWith(editor);editor.focus();editor.select();let cancelled=false,done=false;
  function finish(){if(done)return;done=true;if(!cancelled&&editor.value.trim()){n.label=editor.value.trim();save()}renderBoard()}
  editor.addEventListener('blur',finish);
  editor.addEventListener('keydown',e=>{if(e.key==='Escape'){cancelled=true;editor.blur()}else if(e.key==='Enter'&&(n.type!=='text'||e.ctrlKey||e.metaKey)){e.preventDefault();editor.blur()}});
}
function clickNode(id){
  if(exampleMode)return;selected=id;
  for(const node of $('#nodes').querySelectorAll('.node'))node.classList.toggle('selected',node.dataset.id===id);
  $('#rename-selected').disabled=false;
}
function editEdgeLabel(index,labelEl){
  if(exampleMode)return;const edge=work().edges[index];if(!edge)return;
  const board=$('#board'),r=labelEl.getBoundingClientRect(),br=board.getBoundingClientRect();
  board.querySelector('.edge-editor')?.remove();const input=document.createElement('input');
  input.className='edge-editor';input.type='text';input.maxLength=80;input.value=edge.label||'data';input.setAttribute('aria-label','Connection label');
  input.style.left=Math.max(4,r.left-br.left+r.width/2-85)+'px';input.style.top=Math.max(4,r.top-br.top-12)+'px';
  board.appendChild(input);input.focus();input.select();let cancelled=false,done=false;
  function finish(){if(done)return;done=true;if(!cancelled){edge.label=input.value.trim()||'data';save()}input.remove();renderBoard()}
  input.addEventListener('blur',finish);
  input.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();input.blur()}else if(e.key==='Escape'){cancelled=true;input.blur()}});
}
$('#edges').addEventListener('click',e=>{const label=e.target.closest('.edge-label');if(label)editEdgeLabel(Number(label.dataset.edge),label)});
$('#edges').addEventListener('keydown',e=>{const label=e.target.closest('.edge-label');if(label&&(e.key==='Enter'||e.key===' ')){e.preventDefault();editEdgeLabel(Number(label.dataset.edge),label)}});
function boardPoint(e){const r=$('#board').getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top}}
$('#nodes').addEventListener('pointerdown',e=>{
  const el=e.target.closest('.node');if(!el||exampleMode||e.target.closest('input,textarea'))return;
  const n=normalNodes().find(x=>x.id===el.dataset.id);if(!n)return;
  const port=e.target.closest('.node-port');
  if(port){e.preventDefault();e.stopPropagation();linkDrag={from:n.id,el:port};port.setPointerCapture(e.pointerId);const line=$('#drag-line');line.style.display='block';line.setAttribute('x1',n.x+el.offsetWidth);line.setAttribute('y1',n.y+el.offsetHeight/2);line.setAttribute('x2',n.x+el.offsetWidth);line.setAttribute('y2',n.y+el.offsetHeight/2);status('Drop the connector on another card to create an arrow.');return}
  drag={id:n.id,el,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,moved:false};el.setPointerCapture(e.pointerId)
});
$('#nodes').addEventListener('pointermove',e=>{
  if(linkDrag){const p=boardPoint(e),line=$('#drag-line');line.setAttribute('x2',p.x);line.setAttribute('y2',p.y);return}
  if(!drag)return;const n=normalNodes().find(x=>x.id===drag.id);if(!n)return;
  const dx=e.clientX-drag.startX,dy=e.clientY-drag.startY;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;
  n.x=Math.max(0,Math.min($('#board').clientWidth-140,drag.x+dx));n.y=Math.max(0,Math.min($('#board').clientHeight-58,drag.y+dy));
  if(drag.moved){drag.el.style.left=n.x+'px';drag.el.style.top=n.y+'px'}
});
$('#nodes').addEventListener('pointerup',e=>{
  if(linkDrag){const from=linkDrag.from;linkDrag=null;$('#drag-line').style.display='none';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.node');
    if(target&&target.dataset.id!==from&&normalNodes().some(n=>n.id===target.dataset.id)){work().edges.push({from,to:target.dataset.id,label:'data'});save();status('Arrow added. Drag another connector to add more.');renderBoard()}else status('No arrow added. Drop the connector on another card.');return}
  if(!drag)return;const id=drag.id,moved=drag.moved;drag=null;
  if(moved){save();renderBoard();lastTap=null;return}
  const now=Date.now();if(lastTap&&lastTap.id===id&&now-lastTap.time<450){lastTap=null;renameNode(id)}else{clickNode(id);lastTap={id,time:now}}
});
$('#nodes').addEventListener('pointercancel',()=>{drag=null;linkDrag=null;const line=$('#drag-line');if(line)line.style.display='none'});
$('#nodes').addEventListener('keydown',e=>{const el=e.target.closest('.node');if(!el||e.target.closest('input,textarea'))return;if(e.key==='Enter'||e.key===' '){e.preventDefault();clickNode(el.dataset.id)}if(e.key==='F2'){e.preventDefault();renameNode(el.dataset.id)}});
$('#add-component').addEventListener('click',()=>addNode($('#component-type').value));$('#add-note').addEventListener('click',()=>addNode('note'));$('#add-text').addEventListener('click',()=>addNode('text'));$('#rename-selected').addEventListener('click',()=>{if(selected&&!exampleMode)renameNode(selected)});$('#delete-selected').addEventListener('click',()=>{if(!selected||exampleMode){toast('Select a card first.');return}work().nodes=normalNodes().filter(n=>n.id!==selected);work().edges=work().edges.filter(e=>e.from!==selected&&e.to!==selected);selected=null;save();renderBoard()});$('#show-example').addEventListener('click',()=>{exampleMode=!exampleMode;selected=null;linkDrag=null;status(exampleMode?'Worked diagram for the current step. Switch back to continue drawing.':'Your whiteboard is ready.');renderBoard()});$('#case-select').addEventListener('change',e=>{db.caseId=e.target.value;db.step=0;selected=null;exampleMode=false;save();renderCourse()});$('#lesson-nav').addEventListener('click',e=>{const b=e.target.closest('[data-step]');if(!b)return;db.step=Number(b.dataset.step);exampleMode=false;selected=null;save();renderCourse()});$('#reasoning').addEventListener('input',e=>{work().notes[db.step]=e.target.value;save();const completed=Object.values(work().notes).filter(x=>x.trim()).length;$('#progress-label').textContent=`${completed} of ${lessons.length} written reflections`;$('#progress-fill').style.width=`${completed/lessons.length*100}%`});$('#reveal-answer').addEventListener('click',()=>{const p=$('#example-panel');p.hidden=!p.hidden;$('#reveal-answer').textContent=p.hidden?'Reveal worked answer':'Hide worked answer'});$('#next-step').addEventListener('click',()=>{if(db.step===lessons.length-1){const i=cases.findIndex(c=>c.id===db.caseId);db.caseId=cases[(i+1)%cases.length].id;db.step=0;toast('New sample question loaded.')}else db.step++;exampleMode=false;selected=null;save();renderCourse()});$('#reset-work').addEventListener('click',()=>{if(!confirm(`Reset your board and notes for ${caseNow().name}?`))return;db.cases[db.caseId]={nodes:[],edges:[],notes:{}};db.step=0;selected=null;exampleMode=false;save();renderCourse();toast('Case reset.')});window.addEventListener('resize',renderBoard);renderCourse();
